mapper.select:
SELECT workspace_id, user_id, saved_view_id, position, created_at, updated_at
FROM saved_view_pin
WHERE workspace_id = #{workspaceId}
  AND user_id = #{userId}
  AND saved_view_id = #{savedViewId}

SELECT COALESCE(MAX(position), -1)
FROM saved_view_pin
WHERE workspace_id = #{workspaceId} AND user_id = #{userId}

mapper.update:
UPDATE saved_view_pin pin
JOIN (
  SELECT saved_view_id,
         ROW_NUMBER() OVER (ORDER BY position, saved_view_id) - 1 AS new_position
  FROM saved_view_pin
  WHERE workspace_id = #{workspaceId} AND user_id = #{userId}
) ordered ON ordered.saved_view_id = pin.saved_view_id
SET pin.position = ordered.new_position
WHERE pin.workspace_id = #{workspaceId} AND pin.user_id = #{userId}

UPDATE saved_view_pin
SET position = #{position}
WHERE workspace_id = #{workspaceId}
  AND user_id = #{userId}
  AND saved_view_id = #{savedViewId}

mapper.delete:
DELETE FROM saved_view_pin
WHERE workspace_id = #{workspaceId}
  AND user_id = #{userId}
  AND saved_view_id = #{savedViewId}

mapper.select:
SELECT 
FROM saved_view_default selected_default
JOIN saved_view sv
  ON sv.workspace_id = selected_default.workspace_id
 AND sv.id = selected_default.saved_view_id
 AND sv.record_type = selected_default.record_type

WHERE selected_default.workspace_id = #{workspaceId}
  AND selected_default.user_id = #{userId}
  AND selected_default.record_type = #{recordType}
  AND (sv.user_id = #{userId} OR sv.visibility = 'workspace')

SELECT workspace_id, user_id, record_type, saved_view_id, created_at, updated_at
FROM saved_view_default
WHERE workspace_id = #{workspaceId}
  AND user_id = #{userId}
  AND record_type = #{recordType}

mapper.delete:
DELETE FROM saved_view_default
WHERE workspace_id = #{workspaceId}
  AND user_id = #{userId}
  AND record_type = #{recordType}

DELETE FROM saved_view_pin
WHERE workspace_id = #{workspaceId}
  AND saved_view_id = #{savedViewId}
  AND user_id <> #{ownerUserId}

DELETE FROM saved_view_default
WHERE workspace_id = #{workspaceId}
  AND saved_view_id = #{savedViewId}
  AND user_id <> #{ownerUserId}
